from pathlib import Path
import base64
import streamlit as st

st.set_page_config(page_title="E-CV Digital — Abdurrazzaq & Afif", page_icon="👥", layout="wide", initial_sidebar_state="collapsed")
st.markdown("""<style>#MainMenu,footer,header{visibility:hidden}.block-container{padding:0!important;max-width:100%!important}[data-testid="stAppViewContainer"]>.main{padding:0!important}[data-testid="stVerticalBlock"]{gap:0!important}iframe{border:0!important;width:100%!important}</style>""", unsafe_allow_html=True)
base = Path(__file__).parent
html = (base / "static" / "index.html").read_text(encoding="utf-8")
css = (base / "static" / "style.css").read_text(encoding="utf-8")
js = (base / "static" / "script.js").read_text(encoding="utf-8")
html = html.replace('<link rel="stylesheet" href="style.css">', '<style>\n' + css + '\n</style>')
html = html.replace('<script src="script.js" defer></script>', '<script>\n' + js + '\n</script>')

# Embed profile photos and certificate previews directly in the HTML iframe.
for name in ("abdurrazzaq.jpg", "afif-alfiansyah.jpg"):
    path = base / "static" / "foto" / name
    if path.exists():
        uri = "data:image/jpeg;base64," + base64.b64encode(path.read_bytes()).decode("ascii")
        html = html.replace(f'src="foto/{name}"', f'src="{uri}"')
preview_ab = 'data:image/png;base64,'
preview_af = 'data:image/png;base64,'
html = html.replace('<div class="certificate-icon">PDF</div>', '<button type="button" class="certificate-preview-button" data-preview-certificate="abdurrazzaq" aria-label="Perbesar sertifikat Abdurrazzaq"><img class="certificate-preview-image" src="' + preview_ab + '" alt="Pratinjau sertifikat Abdurrazzaq"></button>', 1)
html = html.replace('<div class="certificate-icon green-icon">PDF</div>', '<button type="button" class="certificate-preview-button" data-preview-certificate="afif" aria-label="Perbesar sertifikat Afif"><img class="certificate-preview-image" src="' + preview_af + '" alt="Pratinjau sertifikat Afif Alfiansyah"></button>', 1)

pdf_ab = base64.b64encode((base / "static" / "sertifikat" / "sertifikat-abdurrazzaq.pdf").read_bytes()).decode("ascii")
pdf_af = base64.b64encode((base / "static" / "sertifikat" / "sertifikat-afif-alfiansyah.pdf").read_bytes()).decode("ascii")
html = html.replace('<a class="btn primary" href="sertifikat/sertifikat-abdurrazzaq.pdf" target="_blank" rel="noopener">Lihat Sertifikat ↗</a>', '<button type="button" class="btn primary" data-preview-certificate="abdurrazzaq">Lihat Sertifikat ↗</button>')
html = html.replace('<a class="btn primary" href="sertifikat/sertifikat-afif-alfiansyah.pdf" target="_blank" rel="noopener">Lihat Sertifikat ↗</a>', '<button type="button" class="btn primary" data-preview-certificate="afif">Lihat Sertifikat ↗</button>')
html = html.replace('<a class="btn secondary" href="sertifikat/sertifikat-abdurrazzaq.pdf" download>Unduh PDF ↓</a>', '<a class="btn secondary" href="#" data-download-certificate="abdurrazzaq" data-filename="sertifikat-abdurrazzaq.pdf">Unduh PDF ↓</a>')
html = html.replace('<a class="btn secondary" href="sertifikat/sertifikat-afif-alfiansyah.pdf" download>Unduh PDF ↓</a>', '<a class="btn secondary" href="#" data-download-certificate="afif" data-filename="sertifikat-afif-alfiansyah.pdf">Unduh PDF ↓</a>')

modal = """
<div class="certificate-modal" id="certificate-modal" aria-hidden="true" role="dialog" aria-modal="true" aria-label="Pratinjau sertifikat">
<button type="button" class="certificate-modal-close" id="certificate-modal-close" aria-label="Tutup pratinjau">×</button>
<div class="certificate-modal-content"><img id="certificate-modal-image" alt="Pratinjau sertifikat ukuran besar"></div>
<p class="certificate-modal-hint">Klik tombol × atau area gelap untuk menutup pratinjau.</p></div>
<style>
.certificate-preview-button{display:block;width:100%;padding:0;border:1px solid #e4e8f0;border-radius:14px;background:#f7f8fc;overflow:hidden;cursor:zoom-in;margin:0 0 16px}
.certificate-preview-image{display:block;width:100%;height:170px;object-fit:contain;background:#f7f8fc;transition:transform .2s ease}
.certificate-preview-button:hover .certificate-preview-image{transform:scale(1.025)}.certificate-actions button{font:inherit;cursor:pointer}
.certificate-modal{display:none;position:fixed;inset:0;z-index:99999;background:rgba(9,17,32,.88);padding:48px 20px 28px;align-items:center;justify-content:center;flex-direction:column}
.certificate-modal.is-open{display:flex}.certificate-modal-content{width:min(1100px,96vw);max-height:82vh;display:flex;justify-content:center;align-items:center;overflow:auto}
.certificate-modal-content img{display:block;max-width:100%;max-height:80vh;object-fit:contain;background:white;border-radius:6px;box-shadow:0 20px 70px rgba(0,0,0,.35)}
.certificate-modal-close{position:absolute;top:12px;right:22px;width:44px;height:44px;border:0;border-radius:50%;background:#fff;color:#14233b;font-size:32px;line-height:1;cursor:pointer}.certificate-modal-hint{color:#fff;font-size:12px;text-align:center;margin:14px 0 0}
@media(max-width:600px){.certificate-modal{padding:52px 10px 20px}.certificate-preview-image{height:135px}.certificate-modal-content img{max-height:75vh}}
</style>
<script>
(function(){
const previews={abdurrazzaq:PREVIEW_AB,afif:PREVIEW_AF};const pdfs={abdurrazzaq:PDF_AB,afif:PDF_AF};
const modal=document.getElementById('certificate-modal');const modalImage=document.getElementById('certificate-modal-image');
function closeModal(){modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true')}
document.querySelectorAll('[data-preview-certificate]').forEach(function(el){el.addEventListener('click',function(event){event.preventDefault();const key=el.getAttribute('data-preview-certificate');if(!previews[key])return;modalImage.src=previews[key];modal.classList.add('is-open');modal.setAttribute('aria-hidden','false')})});
document.getElementById('certificate-modal-close').addEventListener('click',closeModal);modal.addEventListener('click',function(event){if(event.target===modal)closeModal()});document.addEventListener('keydown',function(event){if(event.key==='Escape')closeModal()});
document.querySelectorAll('[data-download-certificate]').forEach(function(el){el.addEventListener('click',function(event){event.preventDefault();const key=el.getAttribute('data-download-certificate');const raw=atob(pdfs[key]||'');if(!raw)return;const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const blob=new Blob([bytes],{type:'application/pdf'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=el.getAttribute('data-filename')||'sertifikat.pdf';document.body.appendChild(link);link.click();link.remove();setTimeout(function(){URL.revokeObjectURL(url)},1500)})});
})();
</script>
"""
modal = modal.replace('PREVIEW_AB', repr(preview_ab)).replace('PREVIEW_AF', repr(preview_af)).replace('PDF_AB', repr(pdf_ab)).replace('PDF_AF', repr(pdf_af))
html = html.replace('</body>', modal + '\n</body>')
st.iframe(html, height=5000)
